import{_ as a,o as t,c as r,a2 as o}from"./chunks/framework.A5mep7Fe.js";const d=JSON.parse('{"title":"👁️ 02 · 计算机视觉 CV","description":"","frontmatter":{},"headers":[],"relativePath":"04-算法岗-传统深度学习/02-计算机视觉CV.md","filePath":"04-算法岗-传统深度学习/02-计算机视觉CV.md","lastUpdated":1786806808000}'),l={name:"04-算法岗-传统深度学习/02-计算机视觉CV.md"};function i(n,e,s,c,h,u){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="👁️-02-·-计算机视觉-cv" tabindex="-1">👁️ 02 · 计算机视觉 CV <a class="header-anchor" href="#👁️-02-·-计算机视觉-cv" aria-label="Permalink to &quot;👁️ 02 · 计算机视觉 CV&quot;">​</a></h1><blockquote><p>从 CNN 到 ViT。即使大模型时代，CV 岗、多模态岗仍考这些。</p></blockquote><hr><h2 id="一、cnn-卷积神经网络" tabindex="-1">一、CNN（卷积神经网络） <a class="header-anchor" href="#一、cnn-卷积神经网络" aria-label="Permalink to &quot;一、CNN（卷积神经网络）&quot;">​</a></h2><ul><li><strong>卷积</strong>：局部感受野 + 权值共享 → 平移不变、参数少</li><li><strong>池化</strong>：降维、增强平移不变</li><li><strong>经典结构</strong>：LeNet → AlexNet → VGG → ResNet（残差解决退化）→ MobileNet（深度可分离，轻量）</li><li><strong>1×1 卷积</strong>：降维/升维、跨通道交互</li></ul><h2 id="二、目标检测" tabindex="-1">二、目标检测 <a class="header-anchor" href="#二、目标检测" aria-label="Permalink to &quot;二、目标检测&quot;">​</a></h2><ul><li><strong>Two-stage</strong>：R-CNN 系列（先候选框再分类），精度高速度慢</li><li><strong>One-stage</strong>：YOLO / SSD（端到端一次出框+类），速度快</li><li><strong>Anchor-free</strong>：FCOS / CenterNet（直接预测关键点）</li><li>指标：mAP、IoU</li></ul><h2 id="三、语义-实例分割" tabindex="-1">三、语义/实例分割 <a class="header-anchor" href="#三、语义-实例分割" aria-label="Permalink to &quot;三、语义/实例分割&quot;">​</a></h2><ul><li>语义分割：FCN / U-Net / SegFormer（逐像素分类）</li><li>实例分割：Mask R-CNN</li><li>指标：mIoU</li></ul><h2 id="四、transformer-进-cv-vit" tabindex="-1">四、Transformer 进 CV（ViT） <a class="header-anchor" href="#四、transformer-进-cv-vit" aria-label="Permalink to &quot;四、Transformer 进 CV（ViT）&quot;">​</a></h2><ul><li>把图像切成 patch，当作 token 序列，输入 Transformer</li><li>大数据下 ViT 超越 CNN；小数据下 CNN 仍稳</li><li>混合：ConvNeXt（CNN 现代化）、Swin（分层窗口注意力）</li></ul><h2 id="五、数据增强与训练技巧" tabindex="-1">五、数据增强与训练技巧 <a class="header-anchor" href="#五、数据增强与训练技巧" aria-label="Permalink to &quot;五、数据增强与训练技巧&quot;">​</a></h2><ul><li>翻转/裁剪/色彩抖动/Mixup/CutMix</li><li>预训练+微调、迁移学习</li></ul><h2 id="六、高频追问" tabindex="-1">六、高频追问 <a class="header-anchor" href="#六、高频追问" aria-label="Permalink to &quot;六、高频追问&quot;">​</a></h2><p><strong>Q1：ResNet 残差为什么有效？</strong></p><blockquote><p>允许梯度直连，缓解深层退化；学习「残差 F(x)=H(x)-x」比直接学映射更容易，训练更深更稳定。</p></blockquote><p><strong>Q2：CNN 和 ViT 怎么选？</strong></p><blockquote><p>数据少/实时/端侧 → CNN（ConvNeXt）；大数据追求上限/需与多模态统一 → ViT。现实多混合。</p></blockquote><p><strong>Q3：YOLO 为什么快？</strong></p><blockquote><p>One-stage 端到端，单次前向直接出框与类别，无候选框生成阶段，推理高效。</p></blockquote><hr><p>➡️ 下一步：<a href="./03-自然语言处理NLP">03-自然语言处理 NLP</a></p>',22)])])}const p=a(l,[["render",i]]);export{d as __pageData,p as default};
